grammar_73 = [
    {
        "title": "Participle Clauses (Basic)",
        "explanation": "Participle clauses (-ing or -ed clauses) allow us to combine ideas economically and express relationships such as time, cause, condition, or result without unnecessary conjunctions. They are especially prevalent in formal, business, and academic registers.\n\n1. Present Participle (-ing): Active meaning, representing simultaneous actions, causes, or immediate sequences.\n   Example: 'Reviewing the risk register, the director noticed three open action points.' (= While / Because she was reviewing...)\n\n2. Past Participle (-ed): Passive meaning, representing actions done to the subject.\n   Example: 'Outlined in the scope of work, all deliverable deadlines must be respected.' (= Because they are outlined...)\n\n3. Perfect Participle (Having + past participle): Emphasizes that an action was completed before the main action occurred.\n   Example: 'Having completed the gap analysis, the team designed a customized coaching session.'\n\nCRITICAL RULE (Dangling Participles): The implied subject of the participle clause must match the grammatical subject of the main clause. Writing 'Reviewing the minutes of meeting, the decision was made' is incorrect because 'the decision' cannot review minutes; you must write: 'Reviewing the minutes of meeting, the board confirmed the decision.'",
        "structures": [
            {"pattern": "Present Participle (-ing clause), Subject + Verb: 'Leading the cross-functional team, Sarah resolved several bottlenecks.'"},
            {"pattern": "Past Participle (-ed clause), Subject + Verb: 'Documented in the issue log, the technical glitches were escalated immediately.'"},
            {"pattern": "Perfect Participle (Having + V3), Subject + Verb: 'Having signed the memo of understanding, both executives celebrated the partnership.'"}
        ],
        "examples": [
            {
                "sentence": "Having finalized the executive summary, the director presented the findings to the steering committee.",
                "arabic": "بعد أن أتم الملخص التنفيذي، استعرض المدير النتائج أمام لجنة التوجيه.",
                "usesVocabulary": ["executive summary"]
            },
            {
                "sentence": "Conducting a rigorous internal audit, the compliance officer uncovered deficiencies in the risk register.",
                "arabic": "أثناء إجرائه تدقيقاً داخلياً صارماً، كشف مسؤول الامتثال عن أوجه قصور في سجل المخاطر.",
                "usesVocabulary": ["internal audit", "risk register"]
            },
            {
                "sentence": "Presented with the balanced scorecard, the executive board approved a new talent pipeline initiative.",
                "arabic": "عند عرض بطاقة الأداء المتوازن عليهم، وافق مجلس الإدارة التنفيذي على مبادرة جديدة لرافد الكفاءات.",
                "usesVocabulary": ["balanced scorecard", "talent pipeline"]
            }
        ],
        "commonMistakes": [
            {
                "wrong": "Reviewing the minutes of meeting, several errors were discovered by the secretary.",
                "right": "Reviewing the minutes of meeting, the secretary discovered several errors.",
                "explanation": "Avoid dangling participles. The subject performing the action ('the secretary') must be the subject of the main clause, not 'several errors'."
            },
            {
                "wrong": "Having sign the memo of understanding, they began project execution.",
                "right": "Having signed the memo of understanding, they began project execution.",
                "explanation": "A perfect participle requires 'Having' followed by the past participle (V3), not the base form."
            }
        ]
    }
]

