grammar_74 = [
    {
        "title": "Passive with Modals (must be, can be, should be)",
        "explanation": "Passive modal structures combine modal auxiliary verbs (must, can, should, could, may, might, ought to) with the passive voice. They are essential in academic, journalistic, policy, and technical discourse to describe necessity, possibility, obligation, and recommendations without emphasizing the agent.\n\n1. Present / Future Modals in Passive:\n   Modal + be + Past Participle (V3)\n   - 'Algorithmic bias must be eliminated through rigorous testing.' (Necessity / Obligation)\n   - 'Data sovereignty can be protected with national legislation.' (Possibility / Capability)\n   - 'Digital divide issues should be addressed by governments.' (Recommendation / Moral Duty)\n\n2. Past Modals in Passive:\n   Modal + have been + Past Participle (V3)\n   - 'The zero-day vulnerability should have been patched earlier.' (Unfulfilled past recommendation)\n   - 'The ransomware attack could have been prevented with multi-step verification.' (Past capability / hypothetical)\n   - 'The company's digital twin must have been updated overnight.' (Logical deduction about the past)\n\n3. Register Note: Passive with modals allows objective, authoritative policy writing by focusing attention on the action or affected technology rather than personal opinions.",
        "structures": [
            {"pattern": "Subject + modal + be + past participle: 'Zero-day vulnerabilities must be patched immediately.'"},
            {"pattern": "Subject + modal + have been + past participle: 'The ransomware attack could have been mitigated by multi-step verification.'"},
            {"pattern": "Subject + negative modal + be + past participle: 'Surveillance capitalism cannot be sustained without user consent.'"}
        ],
        "examples": [
            {
                "sentence": "Algorithmic bias must be mitigated before any machine learning model is deployed commercially.",
                "arabic": "يجب الحد من التحيز الخوارزمي قبل نشر أي نموذج لتعلم الآلة تجارياً.",
                "usesVocabulary": ["algorithmic bias", "machine learning model"]
            },
            {
                "sentence": "Data sovereignty can be reinforced when cloud migration complies with international digital regulation.",
                "arabic": "يمكن تعزيز السيادة على البيانات عندما يتوافق الانتقال السحابي مع التنظيم الرقمي الدولي.",
                "usesVocabulary": ["data sovereignty", "cloud migration", "digital regulation"]
            },
            {
                "sentence": "The destructive ransomware attack should have been anticipated by IT security analysts.",
                "arabic": "كان ينبغي على محللي أمن تقنية المعلومات توقع هجوم برامج الفدية المدمر.",
                "usesVocabulary": ["ransomware attack"]
            }
        ],
        "commonMistakes": [
            {
                "wrong": "The filter bubble must addressed by tech companies.",
                "right": "The filter bubble must be addressed by tech companies.",
                "explanation": "A passive modal structure requires the auxiliary verb 'be' before the past participle: 'must be addressed', not 'must addressed'."
            },
            {
                "wrong": "Multi-step verification should has been enforced earlier.",
                "right": "Multi-step verification should have been enforced earlier.",
                "explanation": "After any modal verb, the base form 'have' must always be used in perfect passives: 'should have been', never 'should has been'."
            }
        ]
    }
]

